<template>
    <section class="transcription-workspace" data-testid="editor-transcription" :data-state="state.status" aria-label="自动标记候选">
        <div class="transcription-intro"><div><span class="kicker">AUTOMATIC MARKERS</span><h2>从声音找到标记</h2><p>先完成四轨分离，再选择分析输入。检查模型候选，修正后添加为新标记轨。</p></div><div class="task-actions"><button v-if="!busy" type="button" class="primary" data-testid="transcription-start" :disabled="!state.ftResultId || !state.selectedRoles.length" @click="service.start()">{{ result ? '重新分析' : '生成候选' }}</button><button v-else type="button" data-testid="transcription-cancel" :disabled="['cancelling','clearing'].includes(state.status)" @click="service.cancel()">{{ state.status === 'cancelling' ? '取消中…' : '取消分析' }}</button><span>待下载模型 {{ formatBytes(state.missingModelBytes) }}</span></div></div>
        <div class="input-options" role="group" aria-label="自动标记分析输入"><label v-for="role in TRANSCRIPTION_ROLES" :key="role"><input type="checkbox" :checked="state.selectedRoles.includes(role)" :disabled="busy" @change="toggleRole(role)">{{ INSTRUMENT_LABELS[role] }} <small>{{ role === 'drums' ? 'ADT_STR' : 'Basic Pitch' }}{{ role === 'piano' || role === 'guitar' ? ' · 辅助分离' : ' · FT' }}</small></label></div>
        <p v-if="!state.ftResultId" class="notice">请在「音轨分离」完成当前歌曲的 FT 分离。</p>
        <div v-if="busy" class="task-progress" role="status" data-testid="transcription-progress"><strong>{{ phaseLabel }}</strong><span v-if="state.progress">{{ state.progress.role }} · {{ state.progress.completedUnits }}<template v-if="state.progress.totalUnits !== null"> / {{ state.progress.totalUnits }}</template> · {{ clockTime(state.progress.elapsedMs/1000) }}</span><progress v-if="state.progress?.totalUnits" :value="state.progress.completedUnits" :max="state.progress.totalUnits" /><progress v-else /></div>
        <p v-if="state.message" class="notice" :class="{'error':state.status === 'error' || !!state.errorCode}" :role="state.errorCode ? 'alert' : 'status'" data-testid="transcription-message">{{ state.message }}</p>
        <template v-if="result">
            <div class="result-toolbar"><div><strong>{{ result.candidates.filter(c => !c.deleted).length }} 个候选</strong><span>{{ state.restored ? '本地结果已恢复' : '分析结果' }} · {{ persistenceLabel }}</span></div><button type="button" class="primary" data-testid="transcription-apply" :disabled="busy || state.applied || !result.candidates.some(c => !c.deleted)" @click="service.apply()">{{ state.applied ? '本结果已应用' : '添加为新标记轨' }}</button></div>
            <p class="notice">钢琴、吉他属于乐器候选，可能存在串音或无目标时的误检。短音与长音由分界值决定，改变分界无需重新推理。</p>
            <ul v-if="result.failures.length" class="failures" aria-label="未完成输入"><li v-for="failure in result.failures" :key="failure.role">{{ INSTRUMENT_LABELS[failure.role] }}未完成：{{ failure.message }}（{{ failure.code }}）</li></ul>
            <p v-if="result.truncatedDrumSegments.length" class="notice error" data-testid="transcription-truncation">鼓解码达到 token 上限，以下片段未完整完成：{{ result.truncatedDrumSegments.map(t=>t.toFixed(3)).join('、') }} 秒。</p>
            <div class="audition-tools"><span>当前试听：{{ playback.audition?.label ?? '原曲' }}{{ playback.state === 'buffering' ? ' · 等待数据' : '' }}</span><button type="button" @click="separation.toggleAudition()">{{ playback.audition?.kind === 'ft' && ['playing','buffering'].includes(playback.state) ? '暂停 FT 试听' : '试听 FT 分轨' }}</button><button v-if="state.bundle?.auxiliary" type="button" data-testid="transcription-listen-piano" @click="service.listenAuxiliary('piano')">试听辅助钢琴</button><button v-if="state.bundle?.auxiliary" type="button" data-testid="transcription-listen-guitar" @click="service.listenAuxiliary('guitar')">试听辅助吉他</button><button type="button" @click="separation.returnToOriginal()">返回原曲</button></div>
            <div class="thresholds" role="group" aria-label="音符长短分界"><label v-for="instrument in noteInstruments" :key="instrument">{{ INSTRUMENT_LABELS[instrument] }} <input type="number" min="0" step="10" :value="state.thresholds[instrument] ?? 300" :disabled="busy" :aria-label="`${INSTRUMENT_LABELS[instrument]}长短分界毫秒`" @change="setThreshold(instrument,$event)"> ms</label></div>
            <EditorCandidateTimeline :candidates="filtered" :thresholds="state.thresholds" :duration="duration" :playback="playback" :active="active" @seek="emit('seek',$event)" />
            <div class="review-filters"><label>乐器 <select v-model="instrumentFilter" aria-label="候选乐器筛选"><option value="all">全部</option><option v-for="instrument in instruments" :key="instrument" :value="instrument">{{ INSTRUMENT_LABELS[instrument] }}</option></select></label><label>鼓类别 <select v-model="drumFilter" aria-label="鼓候选类别筛选"><option value="all">全部</option><option v-for="category in drumCategories" :key="category" :value="category">{{ category }}</option></select></label><label><input v-model="showDeleted" type="checkbox">显示已删除</label><span>{{ filtered.length }} 个 · 第 {{ safePage+1 }}/{{ pageCount }} 页</span><button type="button" :disabled="safePage === 0" @click="page = safePage-1">上一页</button><button type="button" :disabled="safePage+1 >= pageCount" @click="page = safePage+1">下一页</button></div>
            <div class="candidate-table app-scrollbar"><table data-testid="transcription-candidates"><thead><tr><th>试听</th><th>原始时间（秒）</th><th>类别 / 音高</th><th>乐器修正</th><th>标记</th><th>强度 / 来源</th><th>处理</th></tr></thead><tbody><tr v-for="candidate in pageCandidates" :key="candidate.id" :data-candidate-id="candidate.id" :class="{deleted:candidate.deleted}"><td><button type="button" :aria-label="`跳转候选 ${candidate.startSeconds.toFixed(3)} 秒`" @click="emit('seek',candidate.startSeconds)">↗</button></td><td>{{ candidate.startSeconds.toFixed(3) }} — {{ candidate.endSeconds.toFixed(3) }}</td><td><select v-if="candidate.kind === 'drum'" :value="candidate.drum" :disabled="busy" aria-label="修正鼓类别" @change="correctDrum(candidate.id,$event)"><option v-for="category in drumCategories" :key="category" :value="category">{{ category }}</option></select><template v-else>{{ pitchLabel(candidate.pitch) }} <small>{{ candidate.pitch }}</small></template></td><td><select v-if="candidate.kind === 'note'" :value="candidate.instrument" :disabled="busy" aria-label="修正候选乐器" @change="correctInstrument(candidate.id,$event)"><option v-for="instrument in noteInstruments" :key="instrument" :value="instrument">{{ INSTRUMENT_LABELS[instrument] }}</option></select><span v-else>鼓</span><small v-if="hints.has(candidate.id)" class="duplicate-hint">跨乐器疑似重复</small></td><td>{{ candidateEventKind(candidate,state.thresholds) === 'point' ? '点' : '区间' }}</td><td>{{ Math.round(candidate.strength*100) }}% <small>{{ candidate.source.inputRole }} / {{ candidate.source.model }}</small></td><td><button type="button" :disabled="busy" :aria-label="candidate.deleted ? '恢复候选' : '删除候选'" @click="service.correct(candidate.id,{deleted:!candidate.deleted})">{{ candidate.deleted ? '恢复' : '删除' }}</button></td></tr></tbody></table><p v-if="!filtered.length" class="notice">当前筛选没有候选。</p></div>
        </template>
        <div class="cache-tools"><button type="button" :disabled="busy" @click="pendingClear = 'results'">清理辅助音频与候选缓存</button><button type="button" :disabled="busy" @click="pendingClear = 'models'">清理新增模型缓存</button><span>工程标记保留；缓存不自动驱逐。</span></div>
        <div v-if="pendingClear" class="cache-confirm" role="group" aria-label="确认清理自动标记缓存"><span>{{ pendingClear === 'results' ? '删除全部自动标记候选与辅助音频？' : '删除新增模型缓存？下次分析需重新下载。' }}</span><button type="button" :disabled="busy" data-testid="transcription-confirm-clear" @click="confirmClear">确认清理</button><button type="button" @click="pendingClear = null">取消</button></div>
    </section>
</template>
<script setup lang="ts">
import { computed,onBeforeUnmount,ref,shallowRef,watch } from 'vue';
import type { PlaybackSnapshot } from '../types/audio';
import { useEditorTranscriptionService } from '../transcription/editorTranscriptionService';
import { useEditorSeparationService } from '../processing/editorSeparationService';
import { TRANSCRIPTION_ROLES,INSTRUMENT_LABELS } from '../transcription/candidateTypes';
import type { CandidateInstrument,DrumCategory,NoteInstrument,TranscriptionRole } from '../transcription/candidateTypes';
import { candidateEventKind,crossInstrumentHints } from '../transcription/candidates';
import { clockTime,formatBytes } from '../processing/presentation';
import EditorCandidateTimeline from './EditorCandidateTimeline.vue';
defineProps<{playback:PlaybackSnapshot;duration:number;active:boolean}>();
const emit = defineEmits<{seek:[seconds:number]}>();
const service = useEditorTranscriptionService(),separation = useEditorSeparationService(),state = shallowRef(service.getSnapshot());
const unsubscribe = service.subscribe(snapshot => { state.value = snapshot; });onBeforeUnmount(unsubscribe);
const noteInstruments:NoteInstrument[] = ['bass','vocals','piano','guitar','unknown'],instruments:CandidateInstrument[] = ['drums',...noteInstruments],drumCategories:DrumCategory[] = ['kick','snare','hat'];
const result = computed(() => state.value.bundle?.result ?? null),busy = computed(() => ['restoring','running','cancelling','clearing'].includes(state.value.status));
const instrumentFilter = ref<CandidateInstrument|'all'>('all'),drumFilter = ref<DrumCategory|'all'>('all'),showDeleted = ref(false),page = ref(0),pendingClear = ref<'results'|'models'|null>(null);
const filtered = computed(() => (result.value?.candidates ?? []).filter(c => (showDeleted.value || !c.deleted) && (instrumentFilter.value === 'all' || c.instrument === instrumentFilter.value) && (drumFilter.value === 'all' || c.kind === 'drum' && c.drum === drumFilter.value)).sort((a,b)=>a.startSeconds-b.startSeconds));
const hints = computed(() => crossInstrumentHints(result.value?.candidates ?? [])),pageCount = computed(() => Math.max(1,Math.ceil(filtered.value.length/100))),safePage = computed(() => Math.min(page.value,pageCount.value-1));
const pageCandidates = computed(() => filtered.value.slice(safePage.value*100,(safePage.value+1)*100));
watch([instrumentFilter,drumFilter,showDeleted,() => result.value?.id],() => { page.value = 0; });
const persistenceLabel = computed(() => ({idle:'尚未保存',saving:'保存修正中',saved:'候选已保存','not-persisted':'修正未保存'})[state.value.persistence]);
const phaseLabel = computed(() => state.value.status === 'restoring' ? '校验并恢复候选' : state.value.status === 'cancelling' ? '取消并释放分析' : state.value.status === 'clearing' ? '清理缓存' : ({'model-download':'下载模型','model-verify':'校验模型','model-load':'载入模型','drum-preprocess':'鼓频谱处理','drum-encoder':'编码鼓片段','drum-decode':'解码鼓击打','drum-segments':'鼓片段完成','pitch-inference':'识别音符','pitch-decode':'整理音符候选','auxiliary-input':'准备辅助分离','auxiliary-inference':'分析钢琴与吉他','auxiliary-persist':'保存辅助音频'}[state.value.progress?.phase ?? ''] ?? state.value.progress?.phase ?? '准备分析'));
function toggleRole(role:TranscriptionRole):void { service.setRoles(state.value.selectedRoles.includes(role) ? state.value.selectedRoles.filter(r=>r!==role) : [...state.value.selectedRoles,role]); }
function setThreshold(instrument:NoteInstrument,event:Event):void { const value = Number((event.target as HTMLInputElement).value);if (Number.isFinite(value) && value >= 0) service.setThreshold(instrument,value); }
function correctDrum(id:string,event:Event):void { service.correct(id,{drum:(event.target as HTMLSelectElement).value as DrumCategory}); }
function correctInstrument(id:string,event:Event):void { service.correct(id,{instrument:(event.target as HTMLSelectElement).value as NoteInstrument}); }
function pitchLabel(pitch:number):string { return `${['C','C♯','D','D♯','E','F','F♯','G','G♯','A','A♯','B'][pitch%12]}${Math.floor(pitch/12)-1}`; }
async function confirmClear():Promise<void> { const kind = pendingClear.value;if (!kind) return;pendingClear.value = null;await service.clear(kind); }
</script>
<style scoped>
.transcription-workspace{padding:24px 0;color:#d6e6dc;font-family:'Segoe UI','Microsoft YaHei',sans-serif}.transcription-intro{display:flex;justify-content:space-between;align-items:center;gap:24px}.kicker{font:10px ui-monospace,monospace;letter-spacing:.16em;color:#93b7a2}h2{font-size:25px;font-weight:500;margin:8px 0}.transcription-intro p{color:#a0b9aa;font-size:13px;margin:8px 0}.task-actions{display:flex;align-items:center;gap:12px;flex-wrap:wrap}.task-actions span,.cache-tools span{font-size:11px;color:#8ca996}button,input,select{border:1px solid #36523f;border-radius:4px;background:#12251a;color:#d4e9dc;padding:6px 9px;font:inherit;font-size:12px}button{cursor:pointer}button:hover{background:#223d2c}button:disabled{opacity:.45;cursor:default}.primary{background:#b6dec5;color:#12261a;border-color:#b6dec5;font-weight:600}.primary:hover{background:#d0eedb}.input-options{display:flex;flex-wrap:wrap;gap:10px;margin:20px 0}.input-options label{border:1px solid #2a4433;padding:10px;border-radius:6px;display:flex;gap:7px;align-items:center;font-size:12px;background:#102017}.input-options small{color:#86a391;font-size:10px}input[type=checkbox]{accent-color:#a3d7b7}.notice{color:#9bb8a7;font-size:12px;line-height:1.7;margin:14px 0}.error,.failures{color:#e1b199}.task-progress{display:flex;align-items:center;flex-wrap:wrap;gap:16px;background:#12251a;padding:14px;border-radius:6px;font-size:12px}.task-progress progress{width:100%;accent-color:#b2dfc0;height:5px}.result-toolbar{display:flex;justify-content:space-between;align-items:center;gap:12px;border-top:1px solid #2d4636;margin-top:24px;padding-top:18px}.result-toolbar strong{font-size:17px;font-weight:500}.result-toolbar span{display:block;font-size:11px;color:#91b09e;margin-top:5px}.failures{font-size:12px;line-height:1.8;padding-left:20px}.audition-tools,.thresholds,.review-filters,.cache-tools,.cache-confirm{display:flex;align-items:center;flex-wrap:wrap;gap:10px;font-size:12px;margin:16px 0}.audition-tools>span{color:#a7c6b5}.thresholds{padding:12px;background:#0c1b12;border:1px solid #263e2e;border-radius:6px}.thresholds label{white-space:nowrap;color:#aac2b3}.thresholds input{width:65px;margin-left:6px}.review-filters label{display:flex;align-items:center;gap:6px}.review-filters>span{margin-left:auto;color:#89a797}.candidate-table{max-height:520px;overflow:auto;border:1px solid #2b4333;border-radius:6px}table{border-collapse:collapse;width:100%;white-space:nowrap;text-align:left;font-size:12px}th{background:#172c1e;color:#a9c6b4;position:sticky;top:0;z-index:1;font-weight:500}td,th{padding:9px;border-bottom:1px solid #263d2d}td small{display:block;color:#89a392;font-size:10px;margin-top:3px}td small.duplicate-hint{color:#dab877}.deleted{opacity:.45}.cache-tools{border-top:1px solid #294231;padding-top:18px;margin-top:24px}.cache-confirm{background:#1c2b1e;border:1px solid #52613a;padding:12px;border-radius:6px}button:focus-visible,input:focus-visible,select:focus-visible{outline:2px solid #badbc1;outline-offset:2px}@media(max-width:700px){.transcription-workspace{padding:18px 10px}.transcription-intro{align-items:flex-start;flex-direction:column;gap:8px}.input-options{gap:6px}.input-options label{padding:8px}.review-filters>span{margin-left:0;width:100%}.result-toolbar{align-items:flex-start}.thresholds{gap:8px}}
</style>
